import inspect
from pgmpy.models import LinearGaussianBayesianNetwork as LGBN
print([x for x in dir(LGBN) if not x.startswith('_')])
print(inspect.signature(LGBN.__init__))
for meth in ['fit', 'fit_params', 'marginal_var', 'predict', 'sample', 'get_parameter']:
    m = getattr(LGBN, meth, None)
    if m is not None:
        try:
            print(meth, inspect.signature(m))
        except Exception:
            print(meth, "(no sig)")
